import java.util.Scanner;

public class Main {
    static long[] f = new long[18];

    static int calculate(long x) {
        int answer, digitCount = 15;
        if (x <= 11L) return (int) Math.min(x, 13 - x);
        while (f[digitCount] >= x) --digitCount;
        answer = (int) ((x / f[digitCount]) * digitCount + calculate(x % f[digitCount]));
        if ((x << 1) < f[digitCount + 1]) return answer;
        return Math.min(answer, digitCount + calculate(f[digitCount + 1] - x) + 1);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        f[1] = 1;
        for (int i = 2; i <= 16; ++i) f[i] = f[i - 1] * 10 + 1;
        long n = scanner.nextLong();
        System.out.println(calculate(n));
        scanner.close();
    }
}
